-- ============================================================
-- SEED: Módulo 11 — Relative Clauses (A2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'relative-clauses';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo relative-clauses não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: who (people)
  (cid,1,1,'gap_fill','The professor ___ teaches advanced linguistics has published over 50 papers.','who',NULL,'"Who" introduces a relative clause referring to a person.','easy'),
  (cid,1,2,'gap_fill','Students ___ study consistently tend to perform better on standardized tests.','who',NULL,'"Who" for people as subject of the relative clause.','easy'),
  (cid,1,3,'multiple_choice','Choose the correct relative pronoun: "The researcher ___ discovered the compound won the Nobel Prize."','who','["which","that","whose","who"]','Use "who" for people in relative clauses.','easy'),
  (cid,1,4,'gap_fill','Anyone ___ wishes to participate in the study should contact the research office.','who',NULL,'"Who" for people — here referring to any person.','easy'),
  (cid,1,5,'gap_fill','The candidate ___ was selected has extensive experience in data analysis.','who',NULL,'"Who was selected" = relative clause with passive; who for person.','easy'),
  (cid,1,6,'multiple_choice','Which sentence is correct?','The committee members who reviewed the proposal have extensive experience.','["The committee members which reviewed the proposal have extensive experience.","The committee members that reviewed the proposal have extensive experience. (also correct)","The committee members who reviewed the proposal have extensive experience.","The committee members reviewed the proposal have extensive experience."]','"Who" for people; "that" is also possible in defining relative clauses.','medium'),
  (cid,1,7,'gap_fill','Scholars ___ specialize in this field agree that the theory is flawed.','who',NULL,'"Who" for people as subject of the relative clause.','easy'),

  -- BLOCK 2: which (things)
  (cid,2,8,'gap_fill','The book ___ was recommended by the professor is out of print.','which',NULL,'"Which" introduces a relative clause referring to a thing.','easy'),
  (cid,2,9,'gap_fill','The experiment ___ produced the most reliable results used a double-blind method.','which',NULL,'"Which" for things/experiments as subject of relative clause.','easy'),
  (cid,2,10,'multiple_choice','Choose the correct relative pronoun: "The theory ___ Darwin proposed changed our understanding of evolution."','which','["who","whom","whose","which"]','Use "which" for things (a theory is a thing).','easy'),
  (cid,2,11,'gap_fill','The data ___ was collected over three years supports the hypothesis.','which',NULL,'"Which" for data (a thing) — subject of relative clause.','easy'),
  (cid,2,12,'multiple_choice','Which sentence correctly uses "which"?','The research methodology, which was designed by Professor Kim, was highly innovative.','["The research methodology, who was designed by Professor Kim, was highly innovative.","The research methodology, which was designed by Professor Kim, was highly innovative.","The research methodology, that was designed by Professor Kim, was highly innovative.","The research methodology which was design by Professor Kim was highly innovative."]','"Which" for things in both defining and non-defining clauses.','medium'),
  (cid,2,13,'gap_fill','The university introduced a new policy ___ requires all students to attend at least 80% of classes.','which',NULL,'"Which" for a policy (thing) as subject of relative clause.','medium'),
  (cid,2,14,'gap_fill','The climate model ___ the team developed proved more accurate than previous versions.','which',NULL,'"Which" for thing as object of relative clause (the team developed which/it).','medium'),

  -- BLOCK 3: that (people/things)
  (cid,3,15,'gap_fill','The article ___ she recommended is available in the library database.','that',NULL,'"That" can replace "who" or "which" in defining relative clauses.','easy'),
  (cid,3,16,'multiple_choice','In which sentence can "that" replace "who"?','The student that won the award has exceptional analytical skills.','["The professor, that was well-known, retired last year (non-defining — can''t use that).","The student that won the award has exceptional analytical skills.","That researcher, that published the paper, is brilliant.","The student, that I told you about, graduated last year (non-defining)."]','"That" can be used in defining relative clauses for people.','medium'),
  (cid,3,17,'gap_fill','The only approach ___ has been proven effective in large-scale trials is costly.','that',NULL,'After superlatives and "only," use "that" not "which".','hard'),
  (cid,3,18,'multiple_choice','When must you use "which" instead of "that"?','In non-defining relative clauses','["After people","In defining clauses","In non-defining relative clauses","After superlatives"]','Non-defining relative clauses (with commas) require "which," not "that".','hard'),
  (cid,3,19,'gap_fill','The first study ___ examined this phenomenon was published in 1987.','that',NULL,'After "first" (superlative-like), "that" is preferred.','hard'),
  (cid,3,20,'multiple_choice','Which sentence is correct?','The phenomenon that scientists have observed most frequently is thermal expansion.','["The phenomenon which scientists have observed most frequently is thermal expansion (also OK in formal English).","The phenomenon that scientists have observed most frequently is thermal expansion.","The phenomenon who scientists have observed is thermal expansion (wrong — phenomenon is a thing).","The phenomenon, that scientists have observed, is thermal expansion (no commas with that)."]','"That" in defining relative clause; cannot use "that" with commas.','hard'),
  (cid,3,21,'gap_fill','Everything ___ the professor mentioned in the lecture will be on the exam.','that',NULL,'After "everything," "all," "nothing" — prefer "that".','hard'),

  -- BLOCK 4: where (places) / when (time)
  (cid,4,22,'gap_fill','The laboratory ___ the team conducted the research was state-of-the-art.','where',NULL,'"Where" introduces a relative clause referring to a place.','easy'),
  (cid,4,23,'multiple_choice','Choose the correct relative pronoun: "The university ___ she studied is ranked among the top 50 in the world."','where','["which","that","who","where"]','"Where" for places in relative clauses.','easy'),
  (cid,4,24,'gap_fill','2020 was the year ___ the pandemic fundamentally disrupted global education systems.','when',NULL,'"When" introduces a relative clause referring to a time/year.','medium'),
  (cid,4,25,'multiple_choice','Which sentence correctly uses "where"?','The conference center where the symposium was held can accommodate 2,000 participants.','["The conference center which the symposium was held can accommodate 2,000 participants.","The conference center where the symposium was held can accommodate 2,000 participants.","The conference center that the symposium was held can accommodate 2,000 participants.","The conference center when the symposium was held can accommodate 2,000 participants."]','"Where" for locations in relative clauses.','medium'),
  (cid,4,26,'gap_fill','There are situations ___ using qualitative methods is more appropriate than quantitative ones.','where',NULL,'"Where" for abstract situations/contexts as well as physical places.','hard'),
  (cid,4,27,'multiple_choice','Choose "where" or "when": "The semester ___ she published her first article was the most challenging of her career."','when','["where","that","which","when"]','"When" for a time period (semester).','medium'),
  (cid,4,28,'gap_fill','The 1950s was the decade ___ modern linguistics as a discipline truly emerged.','when',NULL,'"When" for a decade (time reference).','medium'),

  -- BLOCK 5: whose (possession)
  (cid,5,29,'gap_fill','The scientist ___ research on genetics has been widely cited received a major award.','whose',NULL,'"Whose" expresses possession: the scientist''s research.','medium'),
  (cid,5,30,'multiple_choice','Choose the correct relative pronoun: "The student ___ thesis won the departmental prize is now a professor."','whose','["who","which","that","whose"]','"Whose" = possessive relative pronoun for people.','medium'),
  (cid,5,31,'gap_fill','We need researchers ___ expertise spans multiple disciplines.','whose',NULL,'"Whose" for people when referring to something they possess (expertise).','medium'),
  (cid,5,32,'multiple_choice','Which sentence correctly uses "whose"?','The company whose products caused environmental damage was fined heavily.','["The company who products caused environmental damage was fined.","The company which products caused environmental damage was fined.","The company whose products caused environmental damage was fined heavily.","The company that products caused environmental damage was fined."]','"Whose" for possession — can refer to organizations as well as people.','medium'),
  (cid,5,33,'gap_fill','The study ___ methodology was considered groundbreaking has since been replicated.','whose',NULL,'"Whose" for inanimate nouns — the study''s methodology.','hard'),
  (cid,5,34,'multiple_choice','Choose "whose" or "who''s" (who is): "The professor ___ paper I read is giving a lecture today."','whose','["who''s","whose"]','"Whose" = possessive; "who''s" = who is (contraction). Never use who''s as relative pronoun.','hard'),
  (cid,5,35,'gap_fill','Participants ___ data was collected anonymously cannot be identified in the published results.','whose',NULL,'"Whose data" = the participants'' data → possessive "whose".','hard'),

  -- BLOCK 6: defining vs non-defining relative clauses
  (cid,6,36,'multiple_choice','Which sentence uses a NON-DEFINING relative clause (extra information)?','The professor, who has taught here for 30 years, is retiring next month.','["The professor who teaches linguistics is well-known (defining — which professor?).","The professor, who has taught here for 30 years, is retiring next month.","Any student who fails twice must repeat the course (defining).","The book that she recommended is out of print (defining)."]','Non-defining relative clauses use commas and add extra information not needed to identify the noun.','hard'),
  (cid,6,37,'gap_fill','In non-defining clauses, use ___ (not "that") for things.','which',NULL,'"That" cannot be used in non-defining relative clauses — always use which/who/whose.','hard'),
  (cid,6,38,'multiple_choice','Add commas if needed: "Albert Einstein who was born in Germany developed the theory of relativity."','Albert Einstein, who was born in Germany, developed the theory of relativity.','["Albert Einstein who was born in Germany developed the theory of relativity (no commas — incorrect for this non-defining context).","Albert Einstein, who was born in Germany, developed the theory of relativity.","Albert Einstein, that was born in Germany, developed the theory of relativity.","Albert Einstein which was born in Germany developed the theory of relativity."]','Non-defining clause (extra info about a unique noun = Einstein) needs commas and "who," not "that".','hard'),
  (cid,6,39,'gap_fill','The Eiffel Tower, ___ was built in 1889, attracts millions of tourists each year.','which',NULL,'Non-defining clause (commas used) with a thing: use "which."','medium'),
  (cid,6,40,'multiple_choice','Which sentence is DEFINING (essential information)?','The student who scored highest will receive a scholarship.','["The student, who scored highest, will receive a scholarship (non-defining — just one student).","My sister, who lives in Paris, is visiting me next week (non-defining).","The student who scored highest will receive a scholarship.","Oxford University, which was founded in 1096, is highly prestigious (non-defining)."]','Defining clause identifies which student — no commas, essential information.','hard'),
  (cid,6,41,'gap_fill','Oxford University, ___ is one of the oldest in the world, consistently ranks in the top 10 globally.','which',NULL,'Non-defining clause about a unique noun (Oxford) = commas + which.','medium'),
  (cid,6,42,'multiple_choice','Can you use "that" here? "The study, ___ was funded by the government, confirmed previous findings."','No — use "which" because this is a non-defining clause.','["Yes, use ''that'' — always preferred","No — use ''which'' because this is a non-defining clause.","Yes, use ''that'' after a comma","No — use ''who'' because it was funded by people"]','Non-defining relative clauses never use "that."','hard'),

  -- BLOCK 7: omitting the relative pronoun when object
  (cid,7,43,'multiple_choice','In which sentence can the relative pronoun be OMITTED?','The article (that) she recommended is very useful. → "that" can be omitted.','["The professor who teaches this course is brilliant. (subject — cannot omit)","The article (that) she recommended is very useful. → ''that'' can be omitted.","The study whose methodology was innovative was published. (whose — cannot omit)","The city where she studied is in France. (where — cannot omit)"]','Object relative pronouns (who/which/that) can be omitted; subject pronouns cannot.','hard'),
  (cid,7,44,'gap_fill','The paper ___ the professor discussed in class is available online. (Omit the pronoun)','[omit]',NULL,'When the relative pronoun is the object of the clause, it can be omitted in informal/semi-formal English.','hard'),
  (cid,7,45,'multiple_choice','Which pronoun CAN be omitted in the sentence: "The student who I recommended received the scholarship."?','who','["who (object — I recommended whom)","who (subject — cannot omit)"]','"Who" is the object here (I recommended who) — can be omitted.','hard'),
  (cid,7,46,'gap_fill','The methodology ___ the team used was later criticized for its small sample size. (Can the pronoun be omitted? Write "yes" or supply it.)','which / that (yes, can be omitted)',NULL,'Object relative pronoun (methodology that the team used it) — can be omitted.','hard'),
  (cid,7,47,'multiple_choice','Which sentence is correct with the relative pronoun omitted?','The evidence the researchers gathered suggests a new approach is needed.','["The evidence who the researchers gathered suggests a new approach.","The evidence which the researchers gathered suggests a new approach. (with pronoun — also correct)","The evidence the researchers gathered suggests a new approach is needed.","The evidence gathered by the researchers suggests a new approach. (participial phrase — also correct)"]','"That/which" (object) can be omitted.','hard'),
  (cid,7,48,'gap_fill','Can you omit "who" here? "The professor who teaches this module is an expert." Answer: ___.','No — "who" is the subject; subject relative pronouns cannot be omitted.',NULL,'Subject relative pronouns (who/which/that as subject) CANNOT be omitted.','hard'),
  (cid,7,49,'multiple_choice','Which sentence has an OMITTED relative pronoun?','The book she published last year became a bestseller.','["The professor who published the book is well-known.","The book she published last year became a bestseller.","The theory which Darwin proposed changed science.","The university where she studied is in England."]','"That" (object) has been omitted: The book [that] she published...','hard'),

  -- BLOCK 8: mixed relative clauses review
  (cid,8,50,'multiple_choice','Choose the correct sentence.','The data which the team collected over five years revealed unexpected patterns.','["The data who the team collected over five years revealed unexpected patterns.","The data which the team collected over five years revealed unexpected patterns.","The data whose the team collected over five years revealed unexpected patterns.","The data where the team collected over five years revealed unexpected patterns."]','"Which" for things (data); object pronoun can also be omitted here.','medium'),
  (cid,8,51,'gap_fill','The institution ___ she received her doctorate is highly respected in the academic community.','where',NULL,'"Where" for a place (institution = place where she studied).','medium'),
  (cid,8,52,'multiple_choice','Identify the error: "The theory, that Einstein proposed, changed physics forever."','that should be which','["Einstein should be einstein","theory should be theories","that should be which","changed should be change"]','Non-defining clauses (with commas) cannot use "that" — use "which."','hard'),
  (cid,8,53,'gap_fill','Scientists ___ work has been peer-reviewed are considered more credible.','whose',NULL,'"Whose work" = the scientists'' work. Possessive relative pronoun.','medium'),
  (cid,8,54,'multiple_choice','Which sentence is correct?','The year when the policy was implemented saw significant economic changes.','["The year which the policy was implemented saw significant economic changes.","The year where the policy was implemented saw significant economic changes.","The year when the policy was implemented saw significant economic changes.","The year that the policy was implemented saw significant economic changes. (also possible)"]','"When" for years/time periods.','medium'),
  (cid,8,55,'gap_fill','The professor, ___ has been teaching here for 25 years, recently published a groundbreaking study.','who',NULL,'Non-defining clause about a person: who + commas.','medium'),
  (cid,8,56,'multiple_choice','Which relative clause is used for EXTRA information only?','Non-defining relative clause','["Defining relative clause","Identifying clause","Non-defining relative clause","Restrictive clause"]','Non-defining = extra information in commas; defining = essential to identify the noun.','easy'),

  -- BLOCK 9: TOEFL academic contexts
  (cid,9,57,'multiple_choice','[TOEFL Reading] Choose the sentence that most naturally appears in an academic text.','The findings, which contradict earlier research, suggest a need for further investigation.','["The findings, that contradict earlier research, suggest a need for further investigation.","The findings which contradicts earlier research suggest a need for further investigation.","The findings, which contradict earlier research, suggest a need for further investigation.","The findings, who contradict earlier research, suggest a need for further investigation."]','Non-defining clause (commas) about a thing: which. Verb agrees with "findings" (plural).','hard'),
  (cid,9,58,'gap_fill','[TOEFL Reading] Participants ___ responses indicated high levels of stress were more likely to report sleep disturbances.','whose',NULL,'"Whose responses" = the participants'' responses → possessive "whose."','hard'),
  (cid,9,59,'multiple_choice','[TOEFL Listening] The professor says: "Scientists who ___ on climate modeling predict a 2°C increase by 2050."','focus','["focuses","focused","focus","focusing"]','Relative clause: who + present simple (base form for plural antecedent "scientists").','hard'),
  (cid,9,60,'gap_fill','[TOEFL Reading] The region ___ these species were first discovered has been declared a protected area.','where',NULL,'"Where" for a geographical region.','medium'),
  (cid,9,61,'multiple_choice','[TOEFL Reading] Which sentence uses relative clauses most effectively in academic prose?','The methodology, which has been validated in previous studies, ensures the reliability of the results.','["The methodology that has been validated in previous studies ensures the reliability of the results. (defining — also acceptable)","The methodology, which has been validated in previous studies, ensures the reliability of the results.","The methodology, that has been validated in previous studies, ensures the reliability of the results. (error: that with commas)","The methodology which it has been validated in previous studies ensures the reliability."]','Non-defining relative clause with "which" for added academic detail.','hard'),
  (cid,9,62,'gap_fill','[TOEFL Reading] The period ___ industrialization transformed society also saw significant advances in medicine.','when',NULL,'"When" for a historical period.','medium'),
  (cid,9,63,'multiple_choice','[TOEFL Listening] The professor mentions a researcher "whose groundbreaking work on neural plasticity ___." Complete the sentence.','has redefined our understanding of how the brain recovers from injury.','["is defining our understanding of how the brain recovers.","has redefined our understanding of how the brain recovers from injury.","have redefined our understanding of how the brain recovers.","had redefined our understanding of how the brain recovers from injury."]','"Whose work" (singular) → has redefined.','hard'),

  -- BLOCK 10: TOEFL production tasks
  (cid,10,64,'multiple_choice','[TOEFL Reading] Identify the most academic use of a relative clause.','The sample, which consisted of 500 university students, was selected using stratified random sampling.','["The sample which consisted of 500 university students was selected using random sampling. (defining — also possible)","The sample, which consisted of 500 university students, was selected using stratified random sampling.","The sample, that consisted of 500 university students, was selected using stratified random sampling.","The sample who consisted of 500 university students was selected randomly."]','Non-defining (commas) + which for methods section description.','hard'),
  (cid,10,65,'gap_fill','[TOEFL Reading] The country ___ the study was conducted has since implemented policies aimed at reducing the risk factors ___ were identified.','where / that',NULL,'"Where" for the location; "that" (object pronoun) for the identified risk factors.','hard'),
  (cid,10,66,'multiple_choice','[TOEFL Speaking — 45s] Which sentence best uses a relative clause in an academic spoken response?','Researchers who specialize in behavioral economics have shown that people often make irrational financial decisions, which contradicts classical economic theory.','["Researchers which specialize in behavioral economics have shown that people often make irrational decisions.","Researchers who specialize in behavioral economics have shown that people often make irrational financial decisions, which contradicts classical economic theory.","Researchers whose specialize in behavioral economics have shown irrational decisions.","Researchers who specializes in behavioral economics have shown irrational decisions."]','Who (people) + defining clause; which (non-defining) for the contrasting idea.','hard'),
  (cid,10,67,'production','[TOEFL Speaking — 45s] Describe a scientist, researcher, or academic figure whose work has influenced your field of interest. Use at least 3 relative clauses: one with "who," one with "whose," and one with "which" (non-defining).','',NULL,'Practice defining (who, whose) and non-defining (which with commas) relative clauses about people and their work.','hard'),
  (cid,10,68,'production','[TOEFL Writing] Write a paragraph (4-5 sentences) describing a research study. Include: a defining relative clause with "which" or "that," a non-defining clause with commas and "which," a "whose" clause, and a "where" clause indicating the location of the research.','',NULL,'Integrate multiple relative clause types in academic writing about research methodology.','hard'),
  (cid,10,69,'multiple_choice','[TOEFL Writing] Which sentence best demonstrates academic use of a relative clause in an essay conclusion?','These findings, which have significant implications for public health policy, call for immediate action by governments worldwide.','["These findings which have significant implications for public health policy call for immediate action.","These findings, that have significant implications for public health policy, call for immediate action.","These findings, which have significant implications for public health policy, call for immediate action by governments worldwide.","These findings, which has significant implications for public health policy, calls for immediate action."]','Non-defining (commas + which); subject "findings" = plural → call (not calls).','hard'),
  (cid,10,70,'production','[TOEFL Writing] Write a paragraph introducing an academic topic of your choice. Include: (1) a defining relative clause identifying the topic, (2) a non-defining relative clause providing extra context, (3) a "whose" clause referring to relevant researchers, and (4) a sentence with an omitted relative pronoun (object position).','',NULL,'Demonstrate mastery of all relative clause types in a cohesive academic introduction.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
